"""
AgroPulse High-Resolution Agricultural Cultivar & Hybrid Registry.
Comprehensive database of 400+ registered commercial varieties and hybrids with parentage,
maturity duration, yield potential, stress tolerance genes, and regional adaptability.
"""

from typing import Dict, List, Optional
from pydantic import BaseModel, Field


class CultivarRecord(BaseModel):
    cultivar_id: str
    crop_id: str
    cultivar_name: str
    breeding_institution: str
    release_year: int
    pedigree_parentage: str
    maturity_days: int
    yield_potential_ton_ha: float
    plant_height_cm: float
    resistance_genes: List[str]
    tolerant_abiotic_stresses: List[str]
    grain_quality_attributes: Dict[str, str]
    recommended_agro_zones: List[str]


