def get_cultivar(cultivar_id: str) -> Optional[CultivarRecord]:
    return CULTIVAR_DATABASE.get(cultivar_id)

def list_all_cultivars() -> List[CultivarRecord]:
    return list(CULTIVAR_DATABASE.values())
